package com.xdownload.mobile;
import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
/** User-enabled, visible, non-focusable overlay. Never accesses the clipboard. */
public final class QuickOverlayService extends Service{
 static final String CHANNEL="xdownload.quick.v1";static final int NOTICE=90431;
 WindowManager manager;TextView bubble;boolean registered=false;
 final BroadcastReceiver screen=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){if(bubble==null)return;if(Intent.ACTION_SCREEN_OFF.equals(i.getAction()))bubble.setVisibility(View.GONE);else if(Intent.ACTION_USER_PRESENT.equals(i.getAction())){if(Settings.canDrawOverlays(c))bubble.setVisibility(View.VISIBLE);else stopSelf();}}};
 @Override public IBinder onBind(Intent i){return null;}
 String tr(String ar,String en){return Store.settings(this).getBoolean("english",false)?en:ar;}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 @Override public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"stop".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}if(!Settings.canDrawOverlays(this)){stopSelf();return START_NOT_STICKY;}try{NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"Quick download",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,90432,new Intent(this,QuickDownloadActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent stop=PendingIntent.getService(this,90433,new Intent(this,QuickOverlayService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification notice=new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.stat_sys_download).setContentTitle("X Download Pro").setContentText(tr("زر التنزيل العائم يعمل","Floating shortcut enabled")).setContentIntent(open).setOngoing(true).setOnlyAlertOnce(true).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,tr("إيقاف","Stop"),stop).build()).build();if(Build.VERSION.SDK_INT>=34)startForeground(NOTICE,notice,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(NOTICE,notice);if(bubble==null)showBubble();return START_NOT_STICKY;}catch(RuntimeException ex){stopSelf();return START_NOT_STICKY;}}
 void showBubble(){manager=getSystemService(WindowManager.class);bubble=new TextView(this);bubble.setText("↓");bubble.setGravity(Gravity.CENTER);bubble.setTextColor(0xffffffff);bubble.setTextSize(26);bubble.setContentDescription(tr("تنزيل سريع، اضغط مطولًا للإيقاف","Quick download, long press to stop"));android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(0xe6226bb7);shape.setCornerRadius(dp(24));bubble.setBackground(shape);bubble.setElevation(dp(4));WindowManager.LayoutParams lp=new WindowManager.LayoutParams(dp(48),dp(48),WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,android.graphics.PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.RIGHT;lp.x=dp(8);lp.y=dp(120);bubble.setOnClickListener(v->{KeyguardManager key=getSystemService(KeyguardManager.class);if(key!=null&&key.isKeyguardLocked())return;try{startActivity(new Intent(this,QuickDownloadActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(RuntimeException ignored){}});bubble.setOnLongClickListener(v->{stopSelf();return true;});bubble.setOnTouchListener(new View.OnTouchListener(){float x,y;int ox,oy;boolean moved;public boolean onTouch(View v,MotionEvent ev){switch(ev.getActionMasked()){case MotionEvent.ACTION_DOWN:x=ev.getRawX();y=ev.getRawY();ox=lp.x;oy=lp.y;moved=false;return false;case MotionEvent.ACTION_MOVE:float dx=ev.getRawX()-x,dy=ev.getRawY()-y;if(Math.abs(dx)+Math.abs(dy)>dp(12))moved=true;if(moved){v.cancelLongPress();android.util.DisplayMetrics dm=getResources().getDisplayMetrics();lp.x=Math.max(0,Math.min(dm.widthPixels-dp(48),ox-Math.round(dx)));lp.y=Math.max(0,Math.min(dm.heightPixels-dp(80),oy+Math.round(dy)));try{manager.updateViewLayout(v,lp);}catch(RuntimeException ignored){}return true;}return false;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:if(moved){v.setPressed(false);return true;}return false;default:return false;}}});manager.addView(bubble,lp);IntentFilter f=new IntentFilter(Intent.ACTION_SCREEN_OFF);f.addAction(Intent.ACTION_USER_PRESENT);if(Build.VERSION.SDK_INT>=33)registerReceiver(screen,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(screen,f);registered=true;KeyguardManager key=getSystemService(KeyguardManager.class);if(key!=null&&key.isKeyguardLocked())bubble.setVisibility(View.GONE);}
 @Override public void onDestroy(){if(registered)try{unregisterReceiver(screen);}catch(RuntimeException ignored){}if(manager!=null&&bubble!=null)try{manager.removeView(bubble);}catch(RuntimeException ignored){}bubble=null;stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}